<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue'
import {NButton,NInput,NSelect,NModal,NForm,NFormItem,NInputNumber,NCheckbox,NTag,NSpace,NAlert,useMessage,useDialog} from 'naive-ui'
import {Plus,RefreshCw,Server,Cloud} from '@lucide/vue'
import {state,api,loadServers} from '../store'
const message=useMessage(),dialog=useDialog(),show=ref(false),busy=ref(false),zone=ref(state.servers?.dns.zone_id||''),token=ref(''),target=ref('current'),form=ref<any>({});const data=computed(()=>state.servers)
onMounted(()=>run(loadServers));watch(()=>data.value?.dns.zone_id,v=>{if(!zone.value)zone.value=v||''})
async function run(fn:()=>Promise<unknown>,ok?:string){try{await fn();if(ok)message.success(ok)}catch(e){message.error((e as Error).message)}}
const targets=computed(()=>data.value?[{label:'当前服务器 · '+data.value.current_ip,value:'current'},...data.value.servers.filter((n:any)=>!n.is_self).map((n:any)=>({label:n.name+' · '+n.host,value:n.id,disabled:!n.in_sync}))]:[])
function open(row?:any){form.value={id:row?.id||null,name:row?.name||'',host:row?.host||'',port:row?.port||22,auth:row?.auth||'password',credential:'',passphrase:'',username:'root',auto_sync:row?row.auto_sync!==false:true};show.value=true}
async function save(){busy.value=true;try{await api('/api/servers/save',form.value);form.value.credential='';form.value.passphrase='';show.value=false;await loadServers();message.success('服务器已保存')}catch(e){message.error((e as Error).message)}finally{busy.value=false}}
function time(v:number){return v?new Date(v*1000).toLocaleString('zh-CN',{hour12:false}):'尚未同步'}
async function action(kind:string,id?:string){await run(async()=>{await api('/api/servers/'+kind,{id});await loadServers()})}
async function saveDns(){busy.value=true;try{await api('/api/servers/dns-save',{zone_id:zone.value,token:token.value});token.value='';await loadServers();message.success('Cloudflare 配置已保存')}catch(e){message.error((e as Error).message)}finally{busy.value=false}}
function switchDns(){const n=targets.value.find(n=>n.value===target.value);dialog.warning({title:'切换入口解析',content:`${data.value.domain} → ${n?.label}。节点链接保持不变，已有连接会断开，恢复时间取决于 DNS 缓存和客户端重新连接。`,positiveText:'确认切换',negativeText:'取消',onPositiveClick:()=>action('switch',target.value)})}
function remove(n:any){dialog.warning({title:'移除备用服务器',content:'只移除管理记录，远端服务继续运行。',positiveText:'移除',negativeText:'取消',onPositiveClick:()=>run(async()=>{await api('/api/servers/remove',{id:n.id});await loadServers()})})}
watch(show,v=>{if(!v){form.value.credential='';form.value.passphrase=''}})
</script>
<template><div class="page-heading"><div><div class="eyebrow">INFRASTRUCTURE</div><h1>服务器管理</h1><p>备用部署、配置同步与入口切换</p></div><NButton type="primary" @click="open()"><template #icon><Plus :size="17"/></template>添加备用服务器</NButton></div>
 <template v-if="data"><div class="settings-grid"><article class="panel settings-card"><h2><Server :size="18"/>当前服务器</h2><dl><div><dt>管理服务器</dt><dd class="mono">{{data.current_ip}}</dd></div><div><dt>固定入口域名</dt><dd>{{data.domain}}</dd></div><div><dt>最近切换地址</dt><dd>{{data.dns.active_ip||'尚未切换'}}</dd></div></dl><div class="info-strip">备用同步保留节点端口、认证和链接。</div></article>
 <article class="panel settings-card"><h2><Cloud :size="18"/>Cloudflare DNS</h2><NForm @submit.prevent="saveDns"><NFormItem label="Zone ID"><NInput v-model:value="zone" placeholder="域名概览中的 Zone ID"/></NFormItem><NFormItem label="API Token"><NInput v-model:value="token" type="password" autocomplete="new-password" :placeholder="data.dns.has_token?'留空保留现有 Token':'授权此 Zone 的 DNS 编辑权限'"/></NFormItem><NSpace><NButton type="primary" attr-type="submit" :loading="busy" :disabled="data.job.running">保存配置</NButton><NButton :disabled="data.job.running" @click="action('dns-check')">检查解析</NButton></NSpace></NForm><div class="switch-dns"><NSelect v-model:value="target" :options="targets" aria-label="切换目标服务器"/><NButton :disabled="data.job.running||!data.dns.has_token" @click="switchDns">切换入口</NButton></div></article></div>
 <section class="panel"><div class="section-heading"><h2>备用服务器 <span class="heading-count">{{data.servers.length}}</span></h2><NButton quaternary aria-label="刷新服务器" @click="run(loadServers)"><template #icon><RefreshCw :size="16"/></template></NButton></div><div v-if="!data.servers.length" class="empty-state"><Server :size="32"/><h3>添加一台备用服务器</h3><p>通过 SSH 部署相同线路，准备域名入口切换。</p><NButton @click="open()">添加服务器</NButton></div><div v-else class="server-list"><article v-for="n in data.servers" :key="n.id" class="server-row"><div class="server-avatar"><Server :size="21"/></div><div class="server-info"><h3>{{n.name}} <NTag size="small" :type="n.in_sync?'success':'default'">{{n.is_self?'当前服务器':n.last_error?'检测异常':n.in_sync?'已同步':n.health||'未检测'}}</NTag></h3><p>{{n.host}}:{{n.port}} · {{time(n.last_sync)}}</p><p v-if="n.last_error" class="error-text">{{n.last_error}}</p><small>{{n.auto_sync?'自动同步已开启':'自动同步未开启'}}</small></div><NSpace><NButton size="small" :disabled="data.job.running||n.is_self" @click="open(n)">编辑</NButton><NButton size="small" :disabled="data.job.running||n.is_self" @click="action('check',n.id)">检测</NButton><NButton size="small" type="primary" secondary :disabled="data.job.running||n.is_self" @click="action('sync',n.id)">部署 / 同步</NButton><NButton size="small" quaternary :disabled="data.job.running" @click="remove(n)">移除</NButton></NSpace></article></div></section><NAlert v-if="data.job.message" :type="data.job.ok===false?'error':data.job.running?'info':'success'" class="form-note">{{data.job.message}}</NAlert></template>
 <div v-else class="empty-state">正在读取服务器配置… <NButton @click="run(loadServers)">重试</NButton></div>
 <NModal v-model:show="show" preset="card" :title="form.id?'编辑备用服务器':'添加备用服务器'" class="dialog" :mask-closable="!busy" :closable="!busy"><NForm @submit.prevent="save"><NFormItem label="名称"><NInput v-model:value="form.name" placeholder="备用服务器"/></NFormItem><div class="form-grid"><NFormItem label="公网 IPv4"><NInput v-model:value="form.host" placeholder="服务器 IP"/></NFormItem><NFormItem label="SSH 端口"><NInputNumber v-model:value="form.port" :min="1" :max="65535"/></NFormItem></div><NFormItem label="认证方式"><NSelect v-model:value="form.auth" :options="[{label:'SSH 密码',value:'password'},{label:'SSH 私钥',value:'key'}]"/></NFormItem><NFormItem :label="form.auth==='password'?'root 密码':'SSH 私钥'"><NInput v-model:value="form.credential" :type="form.auth==='password'?'password':'textarea'" autocomplete="new-password" :placeholder="form.id?'留空保留现有凭据':'输入认证凭据'"/></NFormItem><NFormItem v-if="form.auth==='key'" label="私钥口令"><NInput v-model:value="form.passphrase" type="password" autocomplete="new-password"/></NFormItem><NCheckbox v-model:checked="form.auto_sync">首次部署后自动同步配置和证书</NCheckbox></NForm><template #footer><NSpace justify="end"><NButton :disabled="busy" @click="show=false">取消</NButton><NButton type="primary" :loading="busy" @click="save">保存服务器</NButton></NSpace></template></NModal>
</template>
